#include "RecentModel.h"
#include <map>
#include <set>
#include <cmath>
#include <algorithm>
namespace private_input::activity {namespace {
std::string wordId(const Json&e){return e.at("reading").str()+char(31)+e.at("text").str();}
bool accepts(uint64_t day,uint64_t reference){return day<=reference&&day+90>reference;}
Json normalized(Json value,uint64_t reference){auto&b=value["buckets"].items;b.erase(std::remove_if(b.begin(),b.end(),[&](const auto&row){return !accepts(row.at("day").num(),reference);}),b.end());std::sort(b.begin(),b.end(),[](const auto&a,const auto&b){return a.at("day").num()<b.at("day").num();});return value;}
void entry(const Json&j){require(j.kind==Json::Kind::object&&j.fields.size()==2&&j.has("word")&&j.has("buckets"),"recent entry shape");auto legacy=emptyLearning();legacy["entries"]=Json::array({j.at("word")});validateLearning(legacy);auto buckets=j.at("buckets");require(buckets.kind==Json::Kind::array&&buckets.items.size()<=90,"recent bucket count");std::set<uint64_t>days;std::map<std::string,uint64_t>totals;for(const auto&b:buckets.items){require(b.kind==Json::Kind::object&&b.fields.size()==2&&b.has("day")&&b.has("counts"),"bucket shape");auto day=b.at("day").num();require(day<=3000000&&days.insert(day).second,"recent bucket day");auto counters=b.at("counts");require(counters.kind==Json::Kind::object&&!counters.fields.empty()&&counters.fields.size()<=64,"recent bucket counters");for(const auto&p:counters.fields){auto n=p.second.num();require(n>0&&n<=1000000000&&j.at("word").at("counts").has(p.first),"recent count");auto total=j.at("word").at("counts").at(p.first).num();require(totals[p.first]<=total&&n<=total-totals[p.first],"recent exceeds cumulative");totals[p.first]+=n;}}}
}
Json emptyRecent(){return Json::object({{"version",2},{"schemaID","private_pinyin_recency"},{"algorithmVersion",1},{"entries",Json::array()}});}
Json recentProjection(const Json&j){auto legacy=emptyLearning();std::vector<Json>words;for(const auto&e:j.at("entries").items)words.push_back(e.at("word"));legacy["entries"]=Json::array(words);if(j.has("personalLexicon"))legacy["personalLexicon"]=j.at("personalLexicon");return validateLearning(legacy);}
Json validateRecent(const Json&j){require(j.kind==Json::Kind::object&&(j.fields.size()==4||(j.fields.size()==5&&j.has("personalLexicon")))&&j.at("version").num()==2&&j.at("schemaID").str()=="private_pinyin_recency"&&j.at("algorithmVersion").num()==1&&j.dump().size()<=CurrentLearningCapacity.recent_archive_bytes,"recent archive metadata");auto rows=j.at("entries");require(rows.kind==Json::Kind::array&&rows.items.size()<=CurrentLearningCapacity.recent_term_rows,"recent entry count");size_t components=0;for(const auto&e:rows.items){entry(e);for(const auto&b:e.at("buckets").items)components+=b.at("counts").fields.size();}require(components<=CurrentLearningCapacity.recent_components,"recent components");(void)recentProjection(j);return j;}
Json mergeRecent(const Json&a,const Json&b,uint64_t reference){require(reference>=90&&reference<=3000000,"recent policy");validateRecent(a);validateRecent(b);auto words=mergeLearning(recentProjection(a),recentProjection(b));std::map<std::string,Json>left,right;for(const auto&e:a.at("entries").items)left[wordId(e.at("word"))]=e;for(const auto&e:b.at("entries").items)right[wordId(e.at("word"))]=e;std::vector<Json>rows;for(const auto&word:words.at("entries").items){auto key=wordId(word);auto l=left.find(key),r=right.find(key);Json result=Json::object({{"word",word},{"buckets",Json::array()}});if(l==left.end())result["buckets"]=r->second.at("buckets");else if(r==right.end())result["buckets"]=l->second.at("buckets");else{const auto&lw=l->second.at("word");const auto&rw=r->second.at("word");require(lw.at("pinVersion").dump()!=rw.at("pinVersion").dump()||lw.at("pinned").boolean()==rw.at("pinned").boolean(),"recent pin equivocation");if(lw.at("generation").num()!=rw.at("generation").num())result["buckets"]=lw.at("generation").num()>rw.at("generation").num()?l->second.at("buckets"):r->second.at("buckets");else{std::map<uint64_t,Json>days;for(const auto&source:{l->second,r->second})for(const auto&bucket:source.at("buckets").items){auto day=bucket.at("day").num();if(!accepts(day,reference))continue;if(!days.count(day))days[day]=Json::object();for(const auto&p:bucket.at("counts").fields)days[day][p.first]=std::max(days[day].has(p.first)?days[day].at(p.first).num():0,p.second.num());}std::vector<Json>buckets;for(const auto&day:days)buckets.push_back(Json::object({{"day",day.first},{"counts",day.second}}));result["buckets"]=Json::array(buckets);}}rows.push_back(normalized(result,reference));}auto result=emptyRecent();result["entries"]=Json::array(rows);if(words.has("personalLexicon"))result["personalLexicon"]=words.at("personalLexicon");return validateRecent(result);}
Json mergeLegacyRecent(const Json&recent,const Json&legacy,uint64_t reference){validateLearning(legacy);auto projected=emptyRecent();std::vector<Json>rows;for(const auto&w:legacy.at("entries").items)rows.push_back(Json::object({{"word",w},{"buckets",Json::array()}}));projected["entries"]=Json::array(rows);if(legacy.has("personalLexicon"))projected["personalLexicon"]=legacy.at("personalLexicon");return mergeRecent(recent,projected,reference);}
Json confirmRecentDelta(const Json&recent,const Json&before,const Json&after,const std::string&device,uint64_t reference,std::optional<uint64_t>day){auto baseline=mergeLegacyRecent(recent,before,reference),result=mergeLegacyRecent(baseline,after,reference);std::map<std::string,Json>old;for(const auto&e:baseline.at("entries").items)old[wordId(e.at("word"))]=e.at("word");if(day&&accepts(*day,reference))for(auto&e:result["entries"].items){const auto&word=e.at("word");if(word.at("deleted").boolean()||!word.at("counts").has(device))continue;auto id=wordId(word);auto found=old.find(id);auto prior=found==old.end()?0:(found->second.at("counts").has(device)?found->second.at("counts").at(device).num():0);auto count=word.at("counts").at(device).num();if(count!=prior+1||(found!=old.end()&&found->second.at("generation").num()!=word.at("generation").num()))continue;auto&buckets=e["buckets"].items;auto bucket=std::find_if(buckets.begin(),buckets.end(),[&](const auto&b){return b.at("day").num()==*day;});if(bucket==buckets.end()){buckets.push_back(Json::object({{"day",*day},{"counts",Json::object({{device,1}})}}));}else{auto&c=(*bucket)["counts"];c[device]=(c.has(device)?c.at(device).num():0)+1;}}return validateRecent(result);}
std::optional<RecentLocalDelta> confirmedRecentLocalDelta(const Json&before,const Json&after,const std::string&device,std::optional<uint64_t>day){
 if(!day||after.kind!=Json::Kind::object||after.at("deleted").boolean()||!after.at("counts").has(device))return {};
 auto prior=before.kind==Json::Kind::object&&before.at("counts").has(device)?before.at("counts").at(device).num():0;auto count=after.at("counts").at(device).num();
 if(count!=prior+1||(before.kind==Json::Kind::object&&before.at("generation").num()!=after.at("generation").num()))return {};
 return RecentLocalDelta{after.at("reading").str(),after.at("text").str(),after.at("generation").num(),prior,count,*day};
}
Json applyRecentLocalDeltas(const Json&recent,const Json&authoritative,const std::vector<RecentLocalDelta>&deltas,const std::string&device,uint64_t reference){
 auto result=mergeLegacyRecent(recent,authoritative,reference);std::map<std::pair<std::string,uint64_t>,uint64_t>covered;
 for(const auto&e:recent.at("entries").items){const auto&w=e.at("word");covered[{wordId(w),w.at("generation").num()}]=w.at("counts").has(device)?w.at("counts").at(device).num():0;}
 std::map<std::string,Json*>rows;for(auto&e:result["entries"].items)rows[wordId(e.at("word"))]=&e;
 for(const auto&d:deltas){require(d.to==d.from+1,"only confirmed unit recent delta");auto key=d.reading+char(31)+d.text;auto found=rows.find(key);if(found==rows.end())continue;auto&e=*found->second;const auto&w=e.at("word");if(w.at("deleted").boolean()||w.at("generation").num()!=d.generation||!w.at("counts").has(device)||w.at("counts").at(device).num()<d.to)continue;auto&seen=covered[{key,d.generation}];if(d.to<=seen)continue;auto count=d.to-std::max(d.from,seen);seen=d.to;if(!count||!accepts(d.day,reference))continue;
  auto&buckets=e["buckets"].items;auto at=std::find_if(buckets.begin(),buckets.end(),[&](const auto&b){return b.at("day").num()==d.day;});if(at==buckets.end())buckets.push_back(Json::object({{"day",d.day},{"counts",Json::object({{device,count}})}}));else{auto&c=(*at)["counts"];c[device]=(c.has(device)?c.at(device).num():0)+count;}
 }
 return validateRecent(result);
}
double recentScore(const Json&e,std::optional<uint64_t>reference){entry(e);if(e.at("word").at("deleted").boolean())return 0;double frequency=0,shortTerm=0,longTerm=0;for(const auto&p:e.at("word").at("counts").fields)frequency=std::min(1e9,frequency+double(p.second.num()));if(reference)for(const auto&bucket:e.at("buckets").items){auto day=bucket.at("day").num();if(!accepts(day,*reference))continue;double count=0;for(const auto&p:bucket.at("counts").fields)count+=double(p.second.num());auto age=double(*reference-day);if(age<7)shortTerm+=count*std::pow(2,-age/2);longTerm+=count*std::pow(2,-age/30);}return .20*std::log1p(frequency)/std::log1p(1e9)+.55*shortTerm/(shortTerm+4)+.25*longTerm/(longTerm+30);}
}
